def _texte_simple(texte: str) -> str:
    """Copie figée de `contenu.texte_simple` (marques de mise en forme retirées)."""
    texte = re.sub(r"<[^>]+>", "", texte or "")
    texte = re.sub(r"(?m)^\s{0,3}#{1,6}\s+", "", texte)
    texte = re.sub(r"(\*\*|__|~~)(.+?)\1", r"\2", texte)
    texte = re.sub(r"(?<![\w*])[*_](?!\s)(.+?)(?<!\s)[*_](?![\w*])", r"\1", texte)
    texte = re.sub(r"(?m)^\s*[*+]\s+", "- ", texte)
    texte = re.sub(r"\n{3,}", "\n\n", texte)
    return texte.strip()


def descriptions_en_texte_simple(apps, schema_editor):
    Listing = apps.get_model("listings", "Listing")
    for annonce in Listing.objects.exclude(description_md="").only("id", "description_md"):
        propre = _texte_simple(annonce.description_md)
        paragraphes = [p for p in re.split(r"\n\s*\n", propre) if p.strip()]
        rendu = "".join(
            "<p>" + "<br>".join(html.escape(ligne) for ligne in p.splitlines()) + "</p>"
            for p in paragraphes
        )
        Listing.objects.filter(pk=annonce.pk).update(description_md=propre, description_html=rendu)


